"""Generate fair-die samples through Gadepall's C randfun.h uniform generator."""

from pathlib import Path
import subprocess
import tempfile

import numpy as np


def roll_dice(trials: int, seed: int = 2026) -> np.ndarray:
    """Return a (trials, 2) array of die faces generated by randfun.h."""
    if trials <= 0:
        raise ValueError("trials must be positive")

    code_dir = Path(__file__).resolve().parent
    driver = code_dir / "random" / "rng_driver.c"

    with tempfile.TemporaryDirectory(prefix="cbse_randfun_") as temp_dir:
        temp_path = Path(temp_dir)
        executable = temp_path / "rng_driver"
        uniform_file = temp_path / "uniform_samples.txt"

        subprocess.run(
            ["cc", "-std=c11", "-O2", str(driver), "-o", str(executable)],
            check=True,
        )
        subprocess.run(
            [str(executable), str(uniform_file), str(2 * trials), str(seed)],
            check=True,
        )
        uniforms = np.loadtxt(uniform_file, dtype=np.float64)

    # randfun.h returns values in [0, 1]; cap the endpoint so a 1.0 maps to face 6.
    faces = np.minimum((uniforms * 6).astype(np.int64) + 1, 6)
    return faces.reshape(2, trials).T
